'use strict';
(globalThis.ABBATE_QUESTION_TRANSLATIONS||(globalThis.ABBATE_QUESTION_TRANSLATIONS={}))["bg"]={"g-flurpruefung":["Какво включва визуална и функционална проверка преди започване на работа?","Преди първата мисия за деня.","Проверете само нивото на горивото и цвета на автомобила.","Проверете спирачките, кормилното управление, вилиците, гумите и предпазните устройства съгласно инструкциите за експлоатация.","Извършете пробно шофиране с повдигнат товар.","Ежедневната проверка включва важните за безопасността части и функции съгласно инструкциите за експлоатация."],"g-rueckhalt":["Как се справяте със съществуващата система за обезопасяване на водача?","Мотокарът е със задължителна ограничителна система.","Използвайте го правилно, докато шофирате.","Използвайте само върху неравни подове.","Деактивирайте го за кратки пътувания.","Предвидените системи за задържане трябва да се използват в съответствие с инструкциите на производителя; те осигуряват специална защита в случай на преобръщане."],"g-mangelmelden":["Какво се отнася за мотокар с повредена вилка?","При проверка забелязвате ясно огънат зъбец.","Ако е възможно, разпределете товара върху другия зъбец.","Карайте само леки товари до следващото обслужване.","Не използвайте мотокара и докладвайте за дефекта на отговорното лице.","Повреденото товароподемно оборудване може да се повреди; Свързаните с безопасността дефекти изискват изключване до изясняване."],"g-einweisung":["Преминавате към мотокар с различни контроли. Какво е необходимо преди употреба?","Операцията се различава от предишното ви превозно средство.","Инструкции, свързани с устройството и спазване на инструкциите за експлоатация.","Едно кратко обяснение от незаангажиран колега винаги е достатъчно.","Няма допълнителна информация, ако имате лиценз за мотокар.","Общата квалификация не замества необходимата инструкция за действително използваното устройство."],"g-anbaugeraet":["Трябва да използвате прикачен файл. Какво проверявате първо?","Ново оборудване променя начина на поемане на товара.","Дали приспособлението отговаря на одобрението на превозното средство и допустимото натоварване.","Само дали устройството може да се закрепи визуално.","Дали приставката може да се инсталира без документация.","Приставките могат да променят оставащия капацитет на натоварване и центъра на натоварване; Одобренията и информацията за товароносимостта трябва да бъдат проверени."],"g-diagramm":["Защо ви е необходима диаграмата на товароносимост?","Налице е голям товар с център на тежестта далеч навън.","За определяне на най-краткия маршрут.","За оценка на максимално допустимото натоварване в зависимост от височината на повдигане и центъра на товара.","За определяне на капацитета на резервоара.","Допустимите натоварвания зависят между другото от разстоянието на центъра на товара и височината на повдигане."],"g-lastschwerpunkt":["Какво обикновено се случва, когато центърът на тежестта се премести по-напред?","Дълъг товар стърчи далеч пред вилиците.","Допустимата товароносимост може да намалее.","Товароносимостта винаги се увеличава.","Разстоянието не оказва влияние върху момента на преобръщане.","По-голямото разстояние от центъра на товара увеличава преобръщащия момент и може да намали допустимата товароносимост."],"g-gabelabstand":["Как вилиците трябва да вземат подходящ палет?","Искате да вземете равномерно натоварен палет.","С зъбците възможно най-близо и само в единия ъгъл.","С толкова голямо разстояние, че палетът се преобръща настрани.","С подходящо разстояние между зъбците и достатъчна ходова част и опорна площ.","Товарът трябва да се поддържа сигурно и възможно най-равномерно през вилиците."],"g-schieflast":["Товарът е подреден нестабилно. Кое е правилното?","Картонените кутии могат да паднат при повдигане.","Започнете бавно; зарядът се стабилизира сам.","Преди да вземете товара, закрепете го достатъчно или го сглобете отново.","Повдигнете товара над височината на главата, така че да не ви пречи.","Разхлабен или нестабилен товар може да падне и да застраши хората; първо вземете мерки за безопасност."],"g-personen":["Може ли да се вдигне човек на обикновени вилици?","Един колега иска да стигне до светло.","Да, ако колегата е с каска.","Не, само определени и разрешени съоръжения могат да се използват от хора в съответствие със специални изисквания.","Да, ако се приближи само малка височина.","Нормалните вилици не са лична работна платформа; Транспортирането и повдигането на хора е предмет на специални изисквания."],"g-transporthoehe":["Как обикновено транспортирате палет?","Пътят е чист и равен.","С повдигнат товар само доколкото е необходимо и в съответствие с инструкцията за експлоатация.","С повдигнат товар възможно най-високо, за да се вижда по-добре.","При силно наклонена напред повдигаща мачта, независимо от товара.","Ниската транспортна позиция намалява риска от преобръщане и сблъсъци; Инструкциите на устройството са решаващи."],"g-kurvenfahrt":["Защо бързото завиване с мотокар е опасно?","Искате бързо да излезете от тясна пътека.","Защото просто изтощава батерията по-бързо.","Защото мотокарът автоматично управлява по-добре.","Тъй като страничните сили влияят на стабилността и могат да доведат до преобръщане.","При завиване влизат в действие допълнителни сили; скоростта трябва да бъде съобразена с натоварването и условията."],"g-ladebruecke":["Какво проверявате, преди да се качите на товарен мост?","Трябва да карате в камион.","Само дали пътеката изглежда достатъчно широка.","Товароносимост, сигурна опора и защита срещу преместване, както и осигуряване на автомобила.","Само дали свети осветлението.","Товарните мостове и превозните средства трябва да бъдат обезопасени срещу движение и подходящи за товара."],"g-fussgaenger":["Как се държите на объркващо кръстовище с пешеходци?","Визуалните връзки са ограничени.","Карайте със съобразена скорост, спрете при необходимост и осигурете безопасна видимост.","Винаги изисквайте предимство, когато носите товар.","Просто натисни клаксона и продължи да караш.","Пешеходците имат специални нужди от защита; Скоростта, видимостта и комуникацията трябва да бъдат съобразени с маршрута на движение."],"g-batterieladen":["На какво трябва да обърнете специално внимание, когато зареждате батерията на устройството?","Използва се станция за зареждане на батерии.","Мястото за зареждане може да бъде избрано независимо от инструкциите на производителя.","Откритият пламък е разрешен, докато камионът е неподвижен.","Подходяща зона за товарене, достатъчна вентилация и спецификации на производителя, както и защита от пожар и експлозия.","При зареждане могат да възникнат опасности от електрическа енергия, газове и химикали; предвидените защитни мерки трябва да се спазват."],"h-beauftragt":["При какви условия ви е позволено да управлявате самостоятелно въздушна работна платформа?","Трябва да използвате работна платформа в компанията.","Ако имате шофьорска книжка.","Ако сте подходящи, инструктирани или квалифицирани и възложени от работодателя.","Ако някога сте виждали работна платформа.","Работодателят трябва да осигури пригодност, квалификации и назначения в съответствие с оперативните изисквания."],"h-vorpruefung":["Какво трябва да се провери преди започване на работа с автовишката?","Сцената беше навън през нощта.","Визуален и функционален тест съгласно инструкциите на производителя, включително предпазни устройства.","Само цвета и възрастта на сцената.","Дали работният материал вече е на платформата.","Преди употреба машината, контролите, аварийните функции и видимите повреди трябва да бъдат проверени в съответствие с инструкциите за експлоатация."],"h-tragfaehigkeit":["Каква информация определя допустимото натоварване на работния кош?","Двама души биха искали да вземат допълнителни инструменти със себе си.","Хората са свободни да преценят допустимото общо тегло.","Отчита се само теглото на най-тежкия човек.","Не трябва да се превишава спецификацията за товароподемност за хора, инструменти и материали.","Номиналният товар се отнася до общото допустимо натоварване, включително превозвания материал."],"h-untergrund":["Какво обмисляте, преди да поставите сцена с опори?","Работите близо до запълнена зона.","Само в обсега на стрелата.","Проверете носещата способност и равномерността на основата, както и подходящата опора според инструкциите.","На възможно най-малък брой удължени опори.","Недостатъчната почва или неправилната опора могат да доведат до загуба на стабилност."],"h-wind":["Задава се силен вятър. Как го правите?","Откривате се с открита сцена.","Спазвайте ограниченията на производителя и ако те бъдат превишени, спрете работата или свалете безопасно кошницата.","Разширете платформата доколкото е възможно, за да е по-стабилна.","Реагирайте само ако паднат разхлабени предмети.","Условията на вятъра, разрешени от производителя, са ограничения за употреба; Вятърът може да създаде опасни допълнителни сили."],"h-strom":["Трябва да работите близо до въздушен електропровод. Какво е решаващо?","В работната зона има жива линия.","Каската замества спазването на безопасна дистанция.","Просто изолирайте коша и работете без координация.","Изяснете опасната зона и осигурете необходимите защитни разстояния или други подходящи мерки.","Възможен е и електрически пробив без директен контакт; Необходимите защитни мерки трябва да бъдат определени преди началото на операцията."],"h-notablass":["Защо трябва да се знае процедурата за аварийно спускане?","Възможна е повреда на нормалното управление.","Така че в случай на неизправност е възможно безопасно спасяване според устройството.","Така че устройството работи по-бързо при нормална работа.","За заместване на редовното изследване.","Концепциите за аварийно управление, аварийно спускане и спасяване трябва да са известни и да работят преди употреба."],"h-gelaender":["Как постигате допълнителна височина в работната кошница?","Монтажната точка е просто извън обсега ви.","Качете се на оградата на коша.","Поставете дъска върху парапета.","Използвайте подходяща платформа с достатъчна работна височина; не се катерете по парапети.","Катеренето по оградата или импровизираните възвишения застрашава защитата от падане."],"h-psaga":["Какви изисквания важат за личните предпазни средства при падане?","Използвате работна платформа, за която е предвидена система за задържане.","Всяка опорна точка извън кошницата винаги е достатъчна.","Спазвайте оценката на риска, информацията на производителя и подходящите точки за закрепване.","Не използвайте никакво обезопасяване, ако кошницата има парапет.","Дали и какви ЛПС са необходими се определя от оценката на риска, конструкцията на етапа и инструкциите за експлоатация."],"h-verfahren":["Може ли сцената да се мести с повдигната платформа?","Работното място е на няколко метра.","Само ако моделът и условията на работа го позволяват според инструкциите на производителя.","Винаги, докато всички се държат.","Не, никога, независимо от дизайна и одобрението на производителя.","Движението в повдигнато положение зависи от устройството и е разрешено само в рамките на одобрените работни условия."],"h-kollision":["Какво трябва да се организира при работа в близост до кранове или други машини?","Движещите се части могат да достигнат до работната кошница.","Нищо; работната кошница винаги се вижда.","Винаги карайте работната кошница над другите машини.","Координирайте работните зони, за да избегнете сблъсъци или точки на прищипване.","Едновременната работа на машината изисква координирани работни процеси и защита срещу сблъсъци или блокиране."],"h-einstieg":["Как влизате или излизате от работната кошница?","Стигате до кошницата на нивото на земята.","Качете се над външния парапет.","Чрез предвидения достъп в безопасно положение съгласно инструкциите за експлоатация.","Чрез стълба, поставена до него с изпъната стрела.","Трябва да се спазват предвидения достъп и инструкциите на производителя; Неконтролираното изкачване крие риск от падане."],"h-defekt":["Устройството за аварийно спиране не работи. какво правиш","Ще откриете дефекта по време на проверката.","Не използвайте платформата и докладвайте за дефекта.","Продължете да работите, ако нормалните контроли работят.","Залепете превключвателя, така че никой да не го задейства.","Повредата на предпазно устройство е дефект, свързан с безопасността и възпрепятства безопасната работа."],"h-sicht":["Движението не може да се види поради препятствие. Как го правиш?","Трябва да преместите подвижна сцена.","Карайте бавно без видимост.","Просто разчитайте на индикатора за разстояние.","Спрете движението и осигурете видимост или безопасно обучение съгласно инструкциите за работа.","Преди процедурата хората, препятствията и пътищата за движение трябва да бъдат безопасно изследвани."],"h-rettung":["Какво включва планирането на разгръщане при работа на по-големи височини?","Сцената се използва в отдалечен район.","Само планираната продължителност на работа.","Подходяща концепция за спасяване с достъпни, обучени хора и процедури за аварийно спускане.","Предположението, че пожарната ще разреши незабавно всеки проблем.","Ефективното спасяване трябва да бъде организирано предварително, дори ако нормалните контроли се провалят."],"k-befaehigung":["Какво е необходимо за самостоятелно управление на кран?","Нов служител трябва да поеме работата с крана.","Пригодност и изисквана квалификация, инструктаж и съответно задание.","Достатъчна е книжка за управление на автомобил.","Гледането веднъж е достатъчно.","Работа с кран може да се възлага само на квалифицирани и упълномощени лица; Инструкцията за оборудване е част от него."],"k-funktionspruefung":["Какво е необходимо за проверка на крана преди началото на смяната?","Вие поемате вътрешен кран.","Просто прочетете времето на работа на табелката.","Проверете свързаните с безопасността функции и видимите дефекти съгласно инструкциите за експлоатация.","Тествайте крана с максимално натоварване без проверка.","Задължителният оперативен контрол служи за идентифициране на опасни дефекти на ранен етап."],"k-traglast":["Какво е значението на допустимата товароносимост?","Трябва да се вдигне товар.","Това е необвързваща препоръка.","Прилага се само когато куката е напълно прибрана.","Не трябва да се превишава допустимата товароносимост за съответното работно състояние.","Допустимите натоварвания за някои видове кранове могат да зависят от радиуса, положението на стрелата и въоръжението."],"k-personen":["Какво се отнася за хората под висящи товари?","Товарът се премества върху работна зона.","Опасната зона трябва да бъде свободна; никой няма право да стъпва под окачения товар.","Шлемът ви позволява да останете директно под него.","Кратките пресичания са разрешени, ако кранът се движи бавно.","Окачените товари представляват риск от падане и смачкване; Хората трябва да бъдат държани далеч от опасната зона."],"k-signale":["Не можете да видите нападателя и получавате противоречиви сигнали. какво правиш","Комуникацията е неясна.","Продължете последната команда за задвижване.","Спрете движението и ясно изяснете комуникацията.","Поставете товара по-бързо, без консултация.","Безопасното движение на товара изисква ясни сигнали и ясна комуникация."],"k-sicht":["Кой ще осигури подкрепа по време на транспортиране, ако операторът на крана не може да види напълно пътя на товара?","Стълб на залата закрива пътя.","Случайно минаващ човек без предварителна уговорка.","никой; само куката е важна.","Подходящо, инструктирано лице с ясно договорено разбиране.","Ако пътят на товара не се вижда, е необходима подходяща инструкция или друго безопасно решение."],"k-ruck":["Защо трябва да се избягват резките движения на крана?","Тежък товар започва да се люлее.","Те създават допълнителни динамични напрежения и могат да дестабилизират товара.","Те основно намаляват всяко движение на махалото.","Те винаги увеличават номиналната товароносимост.","Силите на ускорение и спиране увеличават напрежението върху крана и сапаните."],"k-sperrbereich":["Какво трябва да проверите, преди да люлеете товар в споделена зона?","Други служители работят наблизо.","Дали товарът визуално съвпада с крана.","Дали опасната зона е обезопасена и няма хора в опасност.","Дали товарът може да се носи възможно най-високо над всички.","Пътищата за завъртане и натоварването трябва да са свободни от незащитени хора."],"k-stuetzen":["Какво е решаващо за мобилен кран с опорни греди?","На частично насипана земя е поставен кран.","Само ширината на пътя.","Цветът на опорните плочи.","Носеща основа, както и опора и разпределение на натоварването според инструкциите за монтаж и производителя.","Инсталацията има значително влияние върху стабилността, особено при променящи се земни условия."],"k-wetter":["Поривът на вятъра кара товара да се люлее значително. Кое е правилното?","Работите на открито.","Спрете безопасно движението и спазвайте допустимите работни условия.","Бързо ускорете движението.","Продължавайте да повдигате товара, въпреки превишаването на ограниченията на производителя.","Вятърът и люлеещите се движения могат да дестабилизират товара и крана; Ограниченията за приложение трябва да се спазват."],"k-freileitung":["Какво се прилага при използване на кранове в близост до въздушни електрически линии?","Стрела или товар може да се приближи до линията.","При непроводим товар луфтовете не са важни.","Изяснете опасната зона и необходимите защитни мерки с отговорните лица преди започване на работа.","Разчитайте само на собствената реакция на оператора на крана.","Съществуват опасности от контакт и прекъсване на напрежението; са необходими безопасни защитни разстояния или други мерки."],"k-sichern":["Какво правите, преди да напуснете крана?","Работата е прекъсната.","Оставете товара да виси окачен.","Оставете крана без надзор с работещо задвижване.","Спуснете товара безопасно и закрепете крана според инструкциите за експлоатация.","Окачените товари не трябва да се оставят без контрол; Кранът и товарът трябва да бъдат паркирани безопасно."],"k-lastanschlag":["Как да разберете дали използвания слинг е подходящ?","Товарът трябва да се повдига с повдигащ колан.","От гледна точка на маркировка, товароносимост, състояние и пригодност за типа прикачен инвентар.","Само по цвета на лентата за повдигане.","Защото вече е използван вчера.","Товароносимостта и състоянието трябва да са достатъчни, като се вземат предвид условията за закрепване."],"k-stopp":["Човек неочаквано влиза в пътя на товара. какво правиш","В момента кранът премества товар.","Незабавно спрете безопасно движението и разчистете опасната зона.","Просто дайте предупредителен сигнал и продължете да шофирате.","Повдигнете товара по-високо и го карайте.","Хората трябва да бъдат защитени от движение на товара; Ако има непосредствена опасност, движението трябва да бъде спряно."],"k-neuerkran":["Ще получите кран с неизвестно управление. Кое е правилното?","Контролите са различни от преди.","Опитайте обичайните ключове, ако подозирате.","Позволете на някой друг без обучение да кара напред.","Получете необходимите инструкции, свързани с устройството, преди самостоятелна употреба.","Дори опитни оператори на кранове се нуждаят от познания за използваните специфични контроли, защитни устройства и ограничения."],"a-kennzeichnung":["Как да разберете допустимата товароносимост на сапана?","Искате да изберете слинг.","Миризмата на материала.","На подходяща, четлива маркировка за товароносимост и информация на производителя.","Относно продължителността на съхранение.","Допустимата товароносимост се определя от етикетирането и условията на работа."],"a-sichtpruefung":["Забелязвате ясен разрез в лентата за повдигане. Как го правиш?","Предполага се, че лентата носи товар.","Не използвайте лентата и я изпратете за тестване или отхвърляне.","Покрийте разреза с лента.","Използвайте го само за особено леки натоварвания.","Повредените текстилни сапани могат да се повредят и трябва да бъдат оценени според критериите за изхвърляне."],"a-neigungswinkel":["Какво се случва, ако ъгълът на наклона на нишките на прашката е по-голям от вертикалата?","Закачалка с две нишки се разпръсква повече.","Силите на нишката винаги намаляват.","Силите на нишките остават същите.","Силите в нишките се увеличават; Трябва да се спазват допустимите ъгли и товароносимост.","С увеличаването на разпространението силата на опън на носеща нишка се увеличава."],"a-schwerpunkt":["Защо трябва да знаете центъра на тежестта на товара?","Натоварването се натрупва неравномерно.","Така че товарът да остане стабилен при повдигане и да не се преобръща неконтролируемо.","За избор на цвят на паласките.","За да може товарът да се върти по-бързо.","Неблагоприятните точки на закрепване или положението на центъра на тежестта могат да доведат до преобръщане, подхлъзване или наклонени склонове."],"a-kantenschutz":["Повдигаща лента лежи срещу остър ръб на компонента. Какво трябва да се направи?","Компонентът трябва да се повдигне.","Повдигнете товара бързо, преди коланът да се повреди.","Използвайте подходяща защита на ръбовете и проверете вида на закрепването.","Почиствайте товарната повърхност само с кърпа.","Острите ръбове могат да повредят поддържащите влакна; оборудването за прашка трябва да бъде съответно защитено."],"a-haken":["На какво обръщате внимание, когато закачате слинг?","Използвате кука за товар.","Поставете прашката отстрани на върха на куката.","Дръжте предпазния капак постоянно отворен.","Заредете куката по предназначение в основата на куката и спазвайте предпазните устройства.","Недопустимото натоварване на върха на куката и липсата на закрепване могат да доведат до нейното откачане."],"a-knoten":["Можете ли да скъсите повдигаща лента, която е твърде дълга, с възел?","Дължината на стопа не пасва.","не; Използвайте само подходящ, одобрен тип прашка или подходящо оборудване за прашка.","Да, ако възелът е опънат много силно.","Да, стига товарът да е неподвижен.","Възлите могат значително да отслабят текстилните ремъци и не са разрешени импровизирани корекции на дължината."],"a-probehub":["Защо товарът първоначално се повдига внимателно?","Искате да транспортирате безопасно.","За да може тя да пътува възможно най-бързо.","За проверка на положението на сапаните, стабилността и центъра на тежестта.","Тъй като товароносимостта се увеличава автоматично.","Контролираният първи ход помага да се открият неправилни спирания и нестабилни позиции на товара."],"a-lastweg":["Къде е позволено да останат хора, докато товарът се транспортира?","Товарът се премества с кран.","Директно под товара със защитна каска.","На бремето, ако могат да издържат.","Извън опасната зона и не под окачени товари.","Дори при внимателно закрепване все още съществуват опасности от падане или люлеене на товари."],"a-haende":["Как избягвате наранявания при отбиване?","Товарът се доближава до опорната повърхност.","Дръжте ръцете и краката далеч от зоната на смачкване и използвайте подходящи помощни средства.","Дръжте товара с голи ръце.","Застанете между товара и стената, за да коригирате позицията.","Между товара и опората възникват опасни точки на прищипване."],"a-vierstraenge":["Какво се отнася за разпределението на натоварването при четирикрако окачване без компенсация на натоварването?","Прикрепен е твърд товар.","И четирите нишки неизбежно носят една и съща сума.","Без доказателство за равномерно разпределение, товароносимостта не може да се използва като обща оценка за четири еднакво натоварени нишки.","Тогава ъгълът на наклона е без значение.","При твърди натоварвания е възможно неравномерно натоварване на нишките; Проектът и допустимата товароносимост трябва да вземат предвид това."],"a-chemikalien":["Какво важи при използване на текстилни сапани в контакт с химикали?","Работите с непозната течност.","Цветът на лентата надеждно показва нейната издръжливост.","Всяка текстилна лента е устойчива на всякакви химикали.","Проверете издръжливостта и информацията за производителя; Не използвайте неподходящи средства.","Химикалите могат да атакуват сапани и незабелязано да намалят тяхната носеща способност."],"a-aufbewahrung":["Как се съхраняват слинговете след употреба?","Мисията приключи.","Чисти, сухи и защитени от повреди според спецификациите на производителя.","Заклещен на земята под незащитен товар.","На всяка остра външна кука.","Подходящото съхранение предотвратява преждевременното износване и улеснява визуалната проверка."],"a-auswahl":["На какво трябва да обърнете специално внимание, когато работите с чувствителни или остри товари?","Боядисан машинен компонент трябва да бъде преместен.","Само транспортната скорост.","Подходящи сапани и защитни мерки за товарната повърхност и ръбовете.","Независимо от товара, винаги един и същ стоманен кабел.","Видът на закрепването и материалът трябва да съответстват на геометрията, повърхността и опасността."],"a-abstimmung":["Операторът на крана няма поглед върху вас. Как давате инструкции?","Вие сте назначен за нападател.","Размахвате на воля, докато започне движение.","Само едно обаждане и си тръгваш.","Чрез ясно договорени знаци или друга надеждна комуникация.","Нападателите и кранистите трябва да комуникират ясно; Ако е неясно, движението трябва да бъде спряно."],"b-qualifikation":["Какво е необходимо на човек, за да работи безопасно с хидравличен багер по време на работа?","Нов човек трябва да поеме работата на строителния обект.","Подходящи квалификации, инструкции, свързани с устройството, и необходимо назначение.","Само книжка за управление на автомобил.","Само едно бързо наблюдение на операцията.","Работодателят трябва да осигури необходимата квалификация и да инструктира оператора по подходящ начин за задачата."],"b-pruefung":["Какво включва ежедневната проверка на машината?","Поемате багер.","Проверете цвета на боята и тапицерията на седалката.","Визуална проверка и функционални тестове съгласно инструкциите за експлоатация, например за течове и повреди.","Движете стрелата с пълна скорост, докато спре.","Повредите на хидравликата, шасито и предпазните устройства могат да доведат до сериозни инциденти."],"b-leitungen":["Какво трябва да се знае за подземните тръби преди изкопни работи?","Трябва да изкопаете канавка.","Само приблизителната дълбочина на планираната изкопна яма.","Цветът на надземната маркировка е достатъчен.","Изяснете местоположението на възможните линии и определете подходящи мерки за сигурност и проучване.","Тръбите за електричество, газ или вода могат да имат животозастрашаващи последици, ако бъдат повредени."],"b-schwenkbereich":["Как защитавате хората в зоната на въртене на багера?","Поемате материал със стрелата.","Оградете или обезопасете опасната зона и дръжте хората далеч.","Преди да завъртите, преместете лопатата бавно.","Карайте над зоната над главите.","Въртящата се надстройка и работното оборудване създават опасност от смачкване и удар."],"b-boeschung":["Какво е важно, когато работите близо до ръба на изкопна яма?","Багерът стои върху установена или насипана земя.","Само дълбочината на копаене определя допустимото разположение.","Обърнете внимание на товароносимостта и закрепването на ръба, както и необходимите разстояния според оценката на риска.","Карайте възможно най-близо до ръба, за да запазите обхвата.","Ако няма достатъчно разстояние или стабилна земя, насипът може да се провали и машината да падне."],"b-standsicherheit":["Защо наклонът и теренът са от решаващо значение за употреба?","Строителната площадка е под наклон.","Машината е еднакво стабилна на всякакви повърхности.","Верижните ходови части елиминират всякакъв риск от преобръщане.","Неравностите и наклоните могат да повлияят на стабилността; Спазвайте ограниченията за приложение.","Стабилността и безопасността при преобръщане зависи от пода, оборудването, товара и положението на машината."],"b-wechselgeraet":["Какво проверявате след смяна на кофа на багер с бърз съединител?","Беше инсталиран нов прикачен файл.","Дали е правилно заключен и обезопасен според инструкциите за експлоатация.","Само дали цветът на лопатата съвпада.","Дали хидравликата работи възможно най-тихо.","Дефектните ключалки могат да причинят падане на приспособленията."],"b-heben":["На какво трябва да обърнете внимание при повдигане на свободно висящ товар с багер?","Багерът се използва за подемни операции.","Решаваща е само обичайната сила на копаене.","Спазвайте допустимото натоварване на повдигане, подходящите точки на закрепване и предписаните защитни устройства.","Товарът може да се закачи за зъбците на кофата.","Повдигането е разрешено само в предвидените работни условия с подходящо оборудване."],"b-rueckwaerts":["Трябва да дадете на заден ход, но не можете да видите пътя. Кое е правилното?","Други работници са наблизо.","Карайте внимателно без видимост.","Просто натисни клаксона и продължи да караш.","Спрете, осигурете видимост и опасната зона или организирайте подходящи инструкции.","Движението на заден ход не трябва да застрашава хората; ограничената видимост изисква допълнителни мерки."],"b-kabel":["Стрелата може да се доближи до въздушен електропровод. какво правиш","Работите на тесен строителен обект.","Предварително уточнете опасната зона и подходящите защитни мерки с отговорните лица.","Игнорирайте линията, ако стрелата е боядисана.","Движете стрелата само особено бързо.","Електрически опасности възникват от контакт и пламък; необходими са безопасни разстояния и защитни мерки."],"b-verlassen":["Как паркирате багера преди да тръгнете?","Починете си.","Оставете стрелата да плава свободно.","Поставете безопасно работното оборудване и обезопасете машината срещу движение и неоторизирана употреба.","Оставете двигателя да работи и кабината отворена.","Сниженото работно оборудване и защитата срещу непреднамерено движение намаляват риска от злополуки."],"b-hydraulik":["Забелязвате хидравлично масло под високо налягане върху повреден тръбопровод. Кое е правилното?","Една линия изтича.","Почувствайте теча с ръката си.","Прикрепете нова скоба под натиск.","Изключете безопасно машината, оставете налягането да се намали и организирайте ремонта да бъде извършен от оторизиран специализиран персонал.","Хидравличната течност под високо налягане може да причини сериозни наранявания; никога не проверявайте за течове на ръка."],"b-unterbau":["Каква е опасността от шофиране по нестабилни повърхности?","Земята е мека след дъжд.","Машината може да потъне, да се плъзне или да се преобърне.","Задвижването автоматично става по-широко.","Това прави диапазона на завъртане по-безопасен.","Недостатъчната товароносимост може значително да наруши стабилността и безопасността при шофиране."],"b-arbeitsgeraet":["Може ли някой да работи под повдигнат инвентар?","Човек иска да контролира нещо под лопатата.","Да, когато двигателят работи на празен ход.","Не, не без необходимата безопасна поддръжка и обезопасяване на работното оборудване.","Да, ако лицето носи предпазна каска.","Хидравличното оборудване може да потъне; Работата по поддръжката изисква сигурно работно оборудване."],"b-geraeteart":["Преминавате от хидравличен багер на челен товарач. Какво се изисква?","Поведението при работа и движение е различно.","Просто същите обувки.","Пробно шофиране без инструкции.","Квалификацията или инструкциите, изисквани за новия тип машина.","Квалификацията трябва да съответства на вида на използваната машина и специфичните оперативни изисквания."],"g-neigung":["Карате натоварен мотокар по наклон. Кое е важното?","Трасето е с ясна денивелация.","Винаги насочвайте товара надолу, дори ако е тежък.","Насочвайте товара нагоре и спазвайте работните указания за шофиране по наклони.","Независимо от посоката на движение, повдигнете вилицата до максимум.","При наклони и спускания товарът винаги трябва да се носи нагоре; Трябва да се спазват инструкциите за превозно средство и експлоатация."],"g-gabelabsenken":["Защо вилицата трябва да е спусната при паркиране?","Мотокарът е паркиран за почивка.","За да могат другите да използват вилицата, за да се изкачат нагоре.","Така че вилицата остава по-видима от разстояние.","Така че повдигането на товара не представлява ненужен риск от спъване или нараняване.","Спуснатите устройства за захващане на товара намаляват риска от инциденти поради стърчащи или необезопасени вилици."],"g-fahrerwechsel":["Колега иска да вземе назаем мотокара. Какво трябва да присъства?","Колегата има само устно разрешение от вас.","Той трябва да има необходимата квалификация и оперативен мандат.","Вашата собствена задача автоматично се отнася и за него.","Свидетелството за управление на личен автомобил е достатъчно за всеки бизнес.","Независимото лидерство е обвързано с личната пригодност, обучение, квалификация и оперативно назначение."],"g-ladungssicherung":["Един палет съдържа разхлабени, подредени една върху друга кутии. Кое е правилното?","Картонена кутия може да падне по време на шофиране.","Осигурете товара срещу подхлъзване и падане преди транспортиране.","Шофирайте бавно само на особено неравен терен.","Компенсирайте разхлабените кутии с по-висока позиция на вилицата.","Товарът трябва да е стабилен и осигурен срещу падане, преди да бъде транспортиран с подемно-транспортното средство."],"g-bodenbelastung":["Пред вас е одеяло с ограничена товароносимост. Как решавате?","Маршрутът води през средно ниво.","Просто обърнете внимание на теглото на камиона без товар.","Изяснете допустимото натоварване на пода за мотокари и товари.","Карайте с инерция, така че таванът да е под натоварване за по-кратък период от време.","Релевантното е общото действително напрежение върху зоната, включително превозно средство, натоварване и динамични влияния."],"g-verkehrswege":["Маркирана пешеходна пътека пресича пътя ви. Кое е правилното?","Пешеходците имат достъп до прелеза по всяко време.","Винаги можете да поискате приоритет с клаксона.","Разрешено е преминаването през маркировката, без да бъдете наблюдавани.","Регулирайте скоростта си, внимавайте за пешеходците и продължавайте да шофирате само когато пътят е свободен.","Маршрутите за движение трябва да се управляват с внимание към хората; Предупредителните знаци не заместват безопасната видимост и чистия маршрут."],"g-parkbremse":["Паркирате мотокар на равен терен. Какво включва това?","Искате да напуснете шофьорската седалка за няколко минути.","Паркирайте, задействайте ръчната спирачка и осигурете срещу неразрешено използване.","Оставете автомобила само в неутрално положение.","Оставете вилицата на височината на главата, така че никой да не я докосва.","Преди да напусне, подемно-транспортното средство трябва да бъде безопасно спряно и осигурено срещу неволно движение."],"g-typenschild":["Коя информация е задължителна, когато става въпрос за товара на мотокар?","Искате да вземете тежка машина.","Очакваният товарен капацитет въз основа на размера на превозното средство.","Информацията на производителя в диаграмата за натоварване или товароносимост.","Теглото на последния транспортиран палет.","Допустимото натоварване се определя от информацията на производителя и зависи между другото от центъра на товара и височината на повдигане."],"g-tore":["Подхождате към нисък проход с мотокар. какво проверяваш","Върху автомобила има извисяващ се товар.","Дали преминаването, включително товара и закрепването, е възможно безопасно.","Само височината на виличния носач без товар.","Дали можете да преминете по-бързо, преди портата да се затвори.","Преди преминаване трябва да се вземат предвид чистата височина и ширина, както и размерите на товара и превозното средство."],"g-reifen":["По време на ежедневната си проверка откривате силно повредена гума. какво правиш","На гумата се виждат повреди, свързани с безопасността.","Карате бавно до редовния си час за поддръжка.","Увеличаваш налягането в гумите и продължаваш да караш.","Не въвеждате автомобила в експлоатация и не докладвате щетите.","Повредените гуми могат да нарушат стабилността и управлението; дефектът трябва да бъде изяснен преди употреба."],"h-absperren":["Служителите минават под работната ви платформа. Какво е необходимо?","Има опасност от падащи инструменти.","Подходяща защитна или ограничена зона под работното място.","Само известие, когато минавате за първи път.","Съхранявайте инструментите възможно най-далеч от ръба на кошницата.","Работната зона под повдигнатите работни места трябва да бъде обезопасена срещу опасност от падащи части."],"h-werkzeuge":["Как транспортирате инструменти в работната кошница?","Необходими са няколко малки инструмента на височина.","Поставете ги свободно върху парапета, така че да са лесно достъпни.","Съхранявайте и закрепете по такъв начин, че да не паднат или да възпрепятстват работата.","Прикрепете към външната страна на парапета в джоба си.","Разхлабените предмети могат да паднат и да застрашат хората; необходимо е сигурно съхранение."],"h-abstuetzung":["Подпора стои върху капак на шахта. Какво трябва да се провери?","Искате да вдигнете платформата.","Просто се уверете, че капакът е сух.","Дали товарът може да се поеме безопасно в тази точка.","Дали не е необходимо да се използват другите опори.","Подпочвата и контактните зони трябва да могат безопасно да поемат поддържащите сили; Кориците трябва да се оценяват отделно."],"h-notaus":["Кога трябва да се използва устройството за аварийно спиране?","Веднага възниква опасно движение.","Само в края на редовна смяна.","За спиране при остра опасност съгласно инструкцията за експлоатация.","Като заместител на планираното понижаване.","Аварийното спиране се използва за предотвратяване на опасност, а не обичайното управление или нормално изключване."],"h-schraegstellung":["Предупреждението за накланяне на сцената реагира. как реагираш","Машината е на наклонена повърхност.","Пренебрегвате предупреждението при ниски работни височини.","Въпреки предупреждението вие карате до най-високата позиция на повдигане.","Спирате и привеждате сцената в безопасно състояние според инструкциите на производителя.","Предупрежденията за накланяне може да показват недостатъчна стабилност; по-нататъшните движения не трябва да увеличават опасността."],"h-umgebung":["Какво трябва да се организира, когато се разполага в близост до зона за движение?","Превозните средства могат да докосват сцената.","Защита срещу сблъсъци и подходящо насочване на трафика.","Завъртете работната кошница доколкото е възможно над пътя.","Само едно предупредително обаждане, преди да стартирате.","Въздушните работни платформи трябва да бъдат защитени срещу сблъсъци с участници в движението; инсталацията трябва да бъде съответно обезопасена."],"h-ueberlast":["Предупреждението за претоварване в кошницата се задейства. какво правиш","Бяха поканени допълнителни инструменти.","Завършете работата с по-висока скорост.","Установете допустимото натоварване на коша и следвайте инструкциите на производителя.","Изключете предупредителния сигнал за постоянно.","Максимално допустимото натоварване на коша, включително хора и материали, не трябва да се превишава."],"h-quetschen":["Закарвате кошницата близо под покрив. Коя опасност е особено важна?","Остава малко място над кошницата.","Затягане или смачкване между коша и конструкцията.","Че двигателят харчи повече гориво.","Че посоката на движение винаги се обръща автоматично.","Тесните пространства над или до работната кошница могат да причинят сериозни наранявания при смачкване."],"h-stromausfall":["Сцената остава на голяма височина без основно задвижване. Кое е правилното?","Нормалното управление на кошницата вече не реагира.","Слизате по стрелата без безопасност.","Чакате до края на смяната си, без да сте информирани.","Започнете подготвеното спасяване с помощта на обучени хора и аварийно спускане.","Трябва да се планира безопасно спасяване при смущения; Обучените хора трябва да познават аварийните функции."],"h-transportstellung":["Как подготвяте сцената за транспорт?","Работната платформа се натоварва на подходящо превозно средство.","Поставете стрелата и платформата в транспортно положение съгласно инструкциите за експлоатация.","Завържете платформата възможно най-навътре.","Оставете опорите разширени, така че да заемат повече място.","Предписаното транспортно положение и закрепване на товара се основават на спецификациите на производителя и транспорта."],"k-bremsprobe":["Какво показва функционалният тест на крановата спирачка преди употреба?","Искате да можете да държите товара сигурно.","Дали спирачката спира и задържа движението по предназначение.","Само дали осветлението на купето работи.","Дали куката може автоматично да държи товар.","Преди употреба функциите, свързани с безопасността, трябва да бъдат проверени съгласно спецификациите."],"k-schraegzug":["Можете ли да теглите страничен товар под ъгъл с крана?","Куката не е вертикално над товара.","Да, ако кранът все още има резервен товар.","Не, товарите не трябва да се теглят с помощта на непозволени диагонални дърпания.","Да, ако прашките са особено къси.","Диагоналното дърпане може да причини неконтролирани движения и допълнително натоварване на крана и сапаните."],"k-verhakt":["На подконструкцията виси товар. Кое е правилното?","При повдигане се усеща съпротивление.","Продължавате да вдигате, докато не излезе.","Премествате товара рязко настрани.","Спирате и закопчаването или запушването се отстранява безопасно.","Заседналите товари не трябва да се разкъсват със сила, тъй като могат да възникнат неприемливи сили."],"k-anzuheben":["Какво проверявате, когато повдигате за кратко висящ товар за първи път?","Товарът се повдига на няколко сантиметра от земята.","Независимо дали виси в равновесие и стопът е сигурен.","Дали човек може да се постави директно под товара.","Дали кранът става по-стабилен чрез бързо завъртане.","Кратко контролирано повдигане се използва за проверка на закрепването, баланса и безопасното поведение на товара."],"k-lastweg":["Къде трябва да бъде транспортният път на товара с кран?","Няколко работни места са под възможния път на натоварване.","Ако е възможно, над заетите работни места.","По планиран, ясен път без хора в риск.","Винаги по диагонал през най-натоварената зона.","Товарните пътища трябва да бъдат организирани по такъв начин, че хората да не бъдат застрашени от висящи товари."],"k-signalverlust":["Радиовръзката с маршала се прекъсва. какво правиш","Не можете да видите самия път на натоварване.","Продължавате движението бавно.","Експериментално се завъртате в предишната посока.","Спирате движението, докато има ясно, сигурно разбиране.","Ако има липса на комуникация, объркващото движение на товара може да не продължи."],"k-haken":["Предпазната кука не се затваря надеждно. Кое е правилното?","При проверката се забелязва дефектно затваряне.","Грешката трябва да бъде коригирана професионално преди по-нататъшна употреба.","Завързвате здраво закопчалката с кабелна връзка.","Използвате куката само за леки товари.","Дефектните закрепващи устройства на товарните куки могат да доведат до откачане на сапани и трябва да бъдат поправени."],"k-zugrichtung":["Какво е важно за вертикалната опора на товара?","Товарът трябва да се повдигне от машина.","Куката на крана трябва да бъде подравнена над центъра на тежестта на товара.","Куката трябва да е разположена възможно най-страни.","Товарът трябва да се избута преди повдигане.","Въздействието на силата, което е възможно най-вертикално над центъра на натоварване, избягва недопустимите странични сили и неконтролираното люлеене навън."],"k-wartung":["На крана се забелязва необичаен шум от смилане. Как го правиш?","Шумът се получава при повдигане.","Покрийте шума чрез по-висока скорост.","Спрете операциите безопасно, докладвайте за дефекти и ги изяснете.","Продължете да работите без предупреждение до почивката.","Забележимите промени могат да показват повреда, свързана с безопасността, и изискват проверка."],"k-absetzen":["Какво трябва да се гарантира при спускане на товар от кран?","Тежък товар е поставен върху повърхност.","Товарът може да лежи необезопасен върху наклонена повърхност.","Сапаните се отстраняват, докато все още плава.","Товарът е стабилен и осигурен срещу обръщане или претъркулване.","Товарът може да бъде освободен от приспособлението за захващане само след като е бил поставен безопасно и е установена стабилност."],"l-schwerpunkt":["Защо центърът на тежестта трябва да се знае, преди да се удари?","Трябва да се транспортира машина с асиметрична форма.","Така че товарът да остане възможно най-балансиран при повдигане.","Така че прашките могат да бъдат избрани толкова дълги, колкото желаете.","Така че допустимата товароносимост не играе роля.","Положението на центъра на тежестта влияе върху разпределението на товара и безопасното равновесие при повдигане."],"l-etikett":["Повдигащата лента няма четлив етикет за товароподемност. Кое е правилното?","Маркировката е станала неузнаваема.","Преценете капацитета на натоварване въз основа на цвета.","Не използвайте колана за повдигане, докато не бъде ясно доказана неговата годност.","Използвайте колана само веднъж за малки товари.","За сапаните са необходими подходящи маркировки; Необяснимата товароносимост изключва безопасен избор."],"l-kantenschutz":["Текстилна лента лежи върху остър стоманен ръб. Какво е необходимо?","Товарът има остри ръбове.","Издърпайте лентата възможно най-здраво без защита.","Изпълнете удара по-бързо.","Използвайте подходяща защита на ръбовете или друго подходящо оборудване за прашка.","Острите ръбове могат да повредят или срежат текстилните ремъци; необходима е подходяща защита."],"l-spreizwinkel":["Как по-големият ъгъл на наклон влияе върху натоварването на сапаните?","Товар се повдига с помощта на две наклонени въжета.","При по-малко благоприятни ъгли, силите в нишките могат да се увеличат.","Силите на нишката изчезват.","Ъгълът няма влияние върху напрежението.","При по-малко благоприятен ъгъл на спиране, силите на нишка могат да се увеличат; Трябва да се спазват таблиците за товароносимост."],"l-knoten":["Може ли въже за прашка да се скъси по желание с помощта на възел?","Въжето е твърде дълго за планираното натоварване.","Да, стегнатият възел подобрява товароносимостта.","Не, използвайте само одобрени методи за скъсяване и закрепване.","Да, ако възелът е закрепен с лента.","Недопустимите възли отслабват сапаните и променят допустимата им товароносимост."],"l-zeichen":["Какво се отнася за комуникацията с лицето, управляващо крана?","Трасето на товара е частично затъмнено.","Няколко души дават различни сигнали едновременно.","Използват се ясни, предварително договорени сигнали.","Никога не се изисква комуникация с радиокранове.","Ясни знаци и ясни отговорности предотвратяват опасни неправилни движения."],"l-sichtpruefung":["Кога трябва да се проверят слинговете за видими дефекти?","Искате да използвате верига за прашка.","Преди употреба обърнете внимание на външни видими повреди.","Само ако вече се е случил инцидент.","Само веднъж при първата покупка.","Преди всяка употреба трябва да се направи оценка на безопасните условия на работа; Видимите повреди възпрепятстват безопасната употреба."],"l-drehung":["Повдигнатият товар започва да се върти неконтролируемо. какво правиш","Товарът се движи по пътя на товара.","Поставяте ръката си между товара и стената.","Поставяте се под товара и го държите.","Спазвате дистанция и оставяте движението да спре контролирано.","Неконтролираните движения на товара създават опасност от смачкване и удар; Хората трябва да напуснат опасната зона."],"l-ablegen":["Кога сапаните могат да бъдат свалени от товара?","Товарът се поставя върху естакади.","Ако товарът е стабилен и осигурен срещу преобръщане или търкаляне.","Веднага щом докосне земята за първи път, независимо от позицията си.","Докато все още виси, за да спестите време.","Сапаните могат да се свалят само след като са поставени безопасно и стабилно."],"l-ketten":["Верижната прашка има силно огъната връзка. какво правиш","Повредата се вижда още преди повдигане.","Увийте повредената зона с тел.","Извадете веригата от употреба и я занесете на професионална проверка.","Повдигнете товара само наполовина.","Деформираните звена на веригата са видими повреди, които могат да попречат на безопасната употреба."],"b-einweiser":["Какво е важно, когато видимостта от багера е ограничена?","Част от сградата закрива зоната за шофиране.","Подходящи визуални мерки или инструкции и ясна комуникация.","Просто гледай качулката.","Карайте през въртящата се зона, въпреки че сте невидими.","Ако видимостта е ограничена, опасностите трябва да бъдат предотвратени чрез допълнителни организационни и технически мерки."],"b-aushub":["Къде може да се съхранява изкопаният материал в близост до строителна яма?","Ръбът на ямата не трябва да бъде изложен на допълнителен риск.","Натрупвайте директно на ръба, така че алеите да останат свободни.","Съхранявайте на достатъчно безопасно разстояние и в съответствие със спецификациите на строителната площадка.","Поставете върху хлабава опора без допълнителни тестове.","Изкопаният материал може да застраши насипи и подпори поради допълнителни товари; Трябва да се спазват безопасни дистанции."],"b-personen":["Позволено ли е на хората да остават в зоната на люлеене, докато багерът се движи?","Човек иска да измерва, докато панорамира.","Да, стига да носи предпазна каска.","Да, ако багерът се люлее бавно.","Не, опасната зона трябва да е свободна преди движение.","Съществува риск от сериозно притискане и наранявания при удар в зоната на завъртане; зоната трябва да се поддържа чиста."],"b-ladung":["Как безопасно транспортирате материал с челен товарач?","Напълнена лопата трябва да се кара през двора.","С подходящо ниско транспортно положение и чист път.","С повдигната лопата за по-добра видимост.","С отворени врати и силен ъгъл на завиване.","Подходящата транспортна позиция намалява риска от преобръщане и подобрява стабилността при шофиране."],"b-anbaupruefung":["Какво проверявате след свързване на приставка?","Беше прикрепена нова лопата.","Само чистотата на боята.","Сигурното заключване и функциониране според инструкциите за експлоатация.","Само дали устройството изглежда по същия начин отвън.","Неправилните ключалки на бързите съединители могат да доведат до неволно освобождаване на приспособленията."],"b-einstieg":["Как безопасно да влезете в кабината на багера?","Стъпалата са мръсни след дъжд.","Качете се в кабината през стрелата.","Качете се на гъсениците с един скок.","Използвайте определени стъпала и дръжки и почистете мръсните стъпала.","Подходящите изкачвания и безопасните точки за задържане намаляват риска от подхлъзване и падане."],"b-graben":["Стената на изкопа показва пукнатини и се руши. Кое е правилното?","Работите точно до канавката.","Спрете работата и накарайте отговорните лица да обезопасят изкопната яма.","Просто карайте по-близо до ръба, за да затворите канавката.","Удълбочете изкопа допълнително без защита.","Пукнатини и движения на земята могат да показват нестабилност и изискват допълнителна оценка на безопасността."],"b-betanken":["На какво обръщате внимание, когато зареждате гориво на земекопна машина?","Резервоарът е почти празен.","Осигурете двигателя и източниците на запалване според инструкциите на производителя и избягвайте разливане.","Винаги зареждайте бензин или дизел в купето.","Пушете при зареждане, когато няма вятър.","Опасностите от пожар и околната среда при работа с гориво изискват подходящи защитни мерки."],"b-laufwerk":["Защо верижите и ходовата част трябва да се проверяват редовно?","Забелязвате необичайни вибрации по време на шофиране.","За да може машината да се движи по-бързо.","Тъй като повредата може да повлияе на безопасното водене и стабилността.","Тъй като работата винаги е разрешена без визуална проверка.","Повредата на задвижването може да повлияе на маневреността, стабилността и безопасната работа."],"b-einweisen":["Какво се изисква при работа в близост до обществено пешеходно движение?","Багер работи директно на ръба на тротоар.","Пешеходците трябва сами да се движат през зоната за люлка.","Просто залепете знак на лопатата.","Ефективно отцепете опасната зона и насочете трафика безопасно.","Трети лица не трябва да влизат в опасната зона на земекопни машини; Необходими са подходящи бариери и насочване на трафика."],"g2-fahrweg":["Има разлята течност по пътя отпред. Как го правиш?","Мотокарът ще премине директно през хлъзгавата зона.","Спрете шофирането и обезопасете или отстранете опасното място.","Преминете през мястото възможно най-бързо с вдигната вилица.","Надявайте се на по-сухи гуми и продължете да карате без промяна.","Замърсените пътища застрашават стабилността и трябва да бъдат подходящо обезопасени, преди да се движите по тях."],"g2-sichtladung":["Висок палет блокира гледката напред. Кое е правилното?","Трябва да шофирате до склад и не можете да видите маршрута.","Повдигнете палета нагоре, докато можете да видите под него.","Шофирайте само като използвате подходящи, безопасни методи, като например движение на заден ход с ясна видимост.","Все още можете да шофирате по пътя без указателна табела или ясна видимост.","Посоката на движение и видимостта трябва да позволяват безопасно наблюдение на маршрута за движение; Товарите не трябва да заместват визуалната проверка."],"g2-fussgaengerstop":["Точно до мотокара спира пешеходец. какво правиш","Човекът е във възможния обхват на шофиране и завъртане.","Изпреварете пешеходеца, като ускорите за кратко.","Минете покрай човека с вдигнат товар.","Спрете и продължете шофирането само на безопасно разстояние.","Хората трябва да стоят далеч от опасната зона; При необходимост пътуването трябва да се прекъсне."],"g2-hubmast":["Забелязвате повреден хидравличен тръбопровод на подемната мачта. Какво се прилага?","Хидравличното масло видимо изтича от машината.","Изведете мотокара от работа и докладвайте за повредата.","Проверете теча на ръка, докато повдигате.","Повдигайте само по-малки товари до края на смяната.","Хидравличните повреди могат да доведат до неконтролирани движения; безопасната употреба не е гарантирана до теста."],"g2-lagerregal":["Искате да съхранявате палет на рафт. Какво проверявате първо?","Нивото на рафта е високо и капацитетът на натоварване трябва да се поддържа.","Натиснете палета върху рафта възможно най-бързо.","Проверете рафтовото отделение, теглото на товара и свободното място за съхранение за пригодност.","Преценете общото тегло въз основа единствено на броя на кутиите.","Рафтовете и оборудването за носене на товари трябва да съответстват на товара и ситуацията на съхранение."],"g2-batterieschaden":["Батерията на мотокара е повредена външно. Кое е правилното?","Преди товарене се забелязват пукнатини или необичайна течност.","Покрийте щетите с лепяща лента и заредете веднага.","Оставете друг човек да зареди батерията, без да я проверявате.","Не зареждайте и не използвайте и информирайте отговорните специалисти.","Повредените батерии представляват електрически и химически опасности и изискват професионална оценка."],"g2-fahrerkabine":["Какво се отнася за разхлабени предмети в зоната на водача?","Инструментите са на пода до педалите за управление.","Отстранете предметите и поддържайте работната зона чиста.","Дръжте инструмента само с един крак, докато шофирате.","Скрийте свободните части под седалката на водача.","Разхлабени предмети могат да блокират педалите и да нарушат безопасната работа на автомобила."],"g2-uebergabe":["Поемате мотокар след смяна на смяна. Какво включва това?","Колега последно е ползвал автомобила.","Да приемем, че колегата е поел всички проверки.","Извършете необходимата проверка и попитайте за известни дефекти.","Започнете пътуването, без да гледате машината.","Лицето, което поема, трябва да се увери, че е в безопасно състояние преди употреба."],"g2-transportsicherung":["Висок предмет е разхлабен върху палета. как действаш","Товарът може да се наклони напред при спиране.","Носете вилицата особено високо, така че товарът да остане стабилен.","Просто карайте кривите бавно, карайте направо по-бързо.","Поставете товара стабилно и го осигурете срещу преобръщане или падане.","Разхлабените товари трябва да бъдат стабилизирани преди транспортиране, така че движенията при спиране и движение да не доведат до падането им."],"g2-arbeitsende":["Какво е важно при необслужван мотокар?","Приключвате смяната си и напускате района.","Паркирайте автомобила безопасно и го осигурете срещу претъркулване и неразрешено използване.","Оставете ключа, за да могат колегите да намерят машината.","Оставете вилицата на нивото на очите, така че да се вижда.","Безопасното паркиране включва манипулиране на спуснат товар и защита срещу движение и неразрешено пускане в експлоатация."],"g2-bremsweg":["Защо трябва да обръщате специално внимание на спирачния път при натоварване?","Мотокарът транспортира тежки товари през складова пътека.","Винаги спирайте по-късно с тежък товар, отколкото без товар.","Регулирайте скоростта към видимостта, земята и условията на натоварване.","При спиране вдигнете рязко товара, за да намалите по-добре.","Масата и състоянието на пътя оказват влияние върху спирачния път; адаптираната скорост е ключова."],"g2-rampe":["Какво проверявате, преди да се изкачите по стръмна рампа?","Маршрутът може да е твърде стръмен за превозното средство.","Карайте по рампата с максимална скорост, независимо от наклона.","Преминете ръба на рампата с повдигнат товар.","Проверете допустимия наклон и безопасния режим на работа от спецификациите на автомобила.","Могат да се използват само рампи в предвидените експлоатационни граници; Инструкциите за експлоатация и контролът на натоварването са решаващи."],"g2-zinke":["Един палет е по-широк от разстоянието на вилицата. Какво трябва да се вземе предвид?","Планирате да поемете необичайно голям товар.","Регулирайте разстоянието на вилицата и точките за монтаж, за да отговарят на товара.","Използвайте само един зъбец, ако товарът е твърде широк.","Повдигнете товара под ъгъл, докато достигне правилната позиция.","Равномерното и подходящо поемане на натоварването намалява приплъзването и преобръщането."],"g2-betriebsanweisung":["Каква е ролята на оперативното регулиране на трафика?","В склада има обозначени еднопосочни и пешеходни зони.","При мотокари се прилагат само правилата за движение по обществения път.","Следвайте посочените маршрути и правилата за движение.","Игнорирайте маркировките, след като превозното средство е натоварено.","Фирмените маршрути и правилата за безопасност предпазват движението на мотокари и пешеходците."],"g2-nothalt":["Кормилното управление реагира необичайно по време на шофиране. Кое е правилното?","Автомобилът вече не може да се управлява както обикновено.","Карайте с по-високи скорости, за да направите управлението по-отзивчиво.","Компенсирайте грешката при особено големи отклонения на волана.","Спрете на безопасно място и проверете автомобила.","Лошото управление застрашава безопасното водене; машината не трябва да продължава да работи неконтролирано."],"g2-anschlagkette":["Искате да преместите свободно висящ товар с мотокар. Какво се прилага?","Товар трябва да виси на кука под вилиците.","Само с одобрено устройство и подходящо оборудване за носене на товари.","Всяка верига ще свърши работа, ако товарът не е тежък.","Затегнете веригата директно между двете вилици.","Свободно висящите товари променят стабилността; Необходими са одобрения от производителя и подходящи съоръжения."],"g2-rollenlast":["Цилиндричен компонент лежи незакрепен върху палет. какво правиш","Товарът може да се търкаля по време на транспортиране.","Приближавайте се към палета особено рязко.","Осигурете компонента срещу търкаляне, преди да вземете палета.","Позиционирайте зъбците достатъчно високо, така че компонентът да не се вижда.","Кръгли или търкалящи се товари изискват надеждна защита срещу промени в позицията."],"g2-pruefplakette":["Как да разберете дали мотокарът може да се използва?","На машината има залепен стикер за проверка.","Всеки стикер винаги замества ежедневната визуална проверка.","Липсата на луфт може да бъде заменена с внимателно шофиране.","В допълнение към проверката на превозното средство, трябва да се вземат предвид валиден тестов статус и експлоатационно одобрение.","Повтарящите се тестове и ежедневните оперативни контроли изпълняват различни функции за безопасност."],"g2-licht":["Осветлението в склада внезапно угасна. Кое е правилното?","Вече не можете безопасно да виждате препятствия по пътя.","Спрете шофирането, докато се гарантира безопасна видимост.","Увеличете скоростта на шофиране, за да напуснете тъмната зона.","Продължете да карате с повдигнати вилици без визуална проверка.","Маршрут, който не може да бъде пренебрегнат безопасно, не трябва да се движи без ефективни мерки за безопасност."],"g2-ueberhang":["Товарът се простира далеч отвъд страната на вилицата. какво проверяваш","Искате да транспортирате палета през тясна врата.","Компенсирайте страничната проекция с бърза крива.","Оценете разстоянието, стабилността и допустимия товароподемност преди шофиране.","Карайте товара с максимална скорост, независимо от формата му.","Надвесите увеличават рисковете от сблъсък и могат да променят стабилността и необходимото пространство за движение."],"g2-wartungsbereich":["Има бариери пред зона за поддръжка. как се държиш","Вашият обичаен маршрут е временно затворен.","Преместете бариерите за кратко и преминете незабелязано.","Карайте директно през работната зона под товар.","Наблюдавайте затварянето и изберете одобрен алтернативен маршрут.","В отцепени зони не може да се влиза или преминава без разрешение."],"g2-bremsprobe":["Кога има смисъл от функционална проверка на работната спирачка?","Подготвяте мотокара преди работа.","Като част от необходимата проверка преди употреба.","Извършвайте само след сериозна авария.","Само ако камионът вече е достигнал висока скорост.","Функционалността на свързаните с безопасността съоръжения се проверява преди употреба."],"g2-fahrzeuganhaenger":["Искате да теглите ремарке с мотокар. Какво се изисква?","Фирмата планира транспорт с прикачен товар.","Вържете всяко ремарке към вилица без проверка.","Спазвайте одобрението на производителя, подходящия съединител и допустимото натоварване на опън.","Просто увеличете налягането в гумите и потеглете.","Работата на влака е възможна само безопасно в рамките на техническите спецификации и с подходяща връзка."],"g2-rueckfahrt":["Какво е важно при движение на заден ход с мотокара?","Има объркваща зона в коридора на склада.","Винаги гледайте само в огледалото за обратно виждане, независимо от обкръжението.","Карайте без видимост, докато клаксона е натиснат веднъж.","Наблюдавайте безопасно маршрута и зоната на хората и, ако е необходимо, ги инструктирайте.","Движението на заден ход изисква ясна видимост или ефективни допълнителни мерки за безопасност."],"g2-lastentnahme":["Изваждате палета от висок рафт. Кое е правилното?","Палитрата може да не е центрирана.","Вземете товара безопасно и го стабилизирайте, преди да го спуснете.","Оставете палета да се завърти настрани, докато го издърпвате.","Проверете под повдигнатия палет, за да видите дали е повреден.","Контролираното повдигане и спускане предотвратява падане на товари и опасни движения."],"h2-absenkweg":["Защо зоната под работната платформа трябва да остане свободна?","Кошът се спуска и под него се поставят материали.","Натиснете материалите надолу с кошницата.","Следете само областта на краката на оператора.","Избягвайте риска от смачкване и сблъсък при спускане.","В зоната за спускане не трябва да има хора или препятствия, които биха могли да бъдат заклещени."],"h2-transporthoehe":["Как премествате подвижна сцена над нисък пасаж?","Просветът е по-нисък от удължената стрела.","Поставете платформата в подходящо транспортно положение съгласно инструкциите за експлоатация.","Оставете стрелата удължена и се придвижете под тавана.","Натиснете кошницата отстрани на рамката на вратата.","За придвижване общата височина и транспортната позиция трябва да съответстват на спецификациите на производителя и на прохода."],"h2-bodenoeffnung":["В пода до сцената има необезопасен отвор. как реагираш","В близост до отвора се намира задвижваща или поддържаща точка.","Поставете опора директно върху ръба на отвора.","Променете мястото на монтаж или потърсете професионална проверка на товароносимостта и закрепването.","Покрийте опасната точка само с картонена кутия.","Отворите и ръбовете могат да се провалят при опорни натоварвания и трябва да бъдат ефективно взети под внимание."],"h2-rettungsperson":["Защо е необходимо втори човек да е запознат с процедурата по спасяване?","Оператор може да стане недееспособен на върха.","Така че работата в кошницата обикновено може да се извършва без охрана.","За да може сцената да се управлява по-бързо от разрешеното.","За да може да се започне безопасно спасяване при спешност.","Концепцията за спасяване трябва да вземе предвид наземната помощ в случай на повреда или извънредна ситуация."],"h2-werkzeugabwurf":["Какво се отнася за инструменти на голяма надморска височина?","Разхлабен инструмент може да падне през ръба на кошницата.","Закрепете инструментите така, че да не застрашават никого или да паднат.","Просто поставете инструменти върху парапета, за да намалите натоварването.","Ако е необходимо, изхвърлете инструментите от кошницата.","Падащи предмети застрашават хората отдолу; Материалът трябва да се съхранява безопасно."],"h2-trittstufe":["Една кутия трябва да служи като допълнително място за стоене в кошницата. Кое е правилното?","В противен случай едва ще стигнете до работното място.","Поставете кутията върху парапета и се качете върху нея.","Не се качвайте на импровизирани възвишения; Използвайте подходящо работно оборудване.","Умишлено заредете кошницата над разрешената височина.","Импровизираните възвишения нарушават предвидената защита срещу падане и не са разрешени."],"h2-lastverteilen":["На какво обръщате внимание, когато в работната кошница има няколко човека?","Двама души работят в коша с тежки инструменти.","Преценете натоварването въз основа единствено на размера на инструмента.","Съхранявайте тежки инструменти директно върху предпазния парапет.","Не превишавайте допустимото натоварване на коша, включително хора и инструменти.","Разрешената товароносимост включва всички хора, материали и инструменти в кошницата."],"h2-abstuetzplatte":["Кога се обмислят допълнителни подложки за опори?","Монтажният под може да понесе само ограничено натоварване.","Ако това е необходимо за безопасно разпределение на натоварването според спецификациите.","За да поставите опорите възможно най-близо до ръба на строителна яма.","За използване на по-дълъг диапазон без информация за производителя.","Необходими са достатъчно контактни зони за безопасни поддържащи сили."],"h2-baugrube":["Сцената трябва да бъде разположена директно на ръба на строителна яма. какво проверяваш","Почвата може да поддаде странично поради изкопната яма.","Разширете подпорите в изкопната яма.","Осигурете достатъчно безопасно разстояние и носеща способност на подложката.","Компенсирайте риска само като повдигнете бавно кошницата.","Изкопните ями могат да повлияят на стабилността поради наклон и пропадане на подпочвата."],"h2-witterung":["Заледяването се образува по време на употреба. как действаш","Контролните повърхности и работната зона стават гладки.","Повдигнете сцената, за да избегнете сняг и лед.","Игнорирайте предупрежденията, докато платформата свети.","Прекъснете работата и преоценете работните условия според инструкциите за експлоатация.","Промените във времето могат да променят отговорността, оперативността и безопасните граници на употреба."],"h2-aufbaukontakt":["Стоманена конструкция ограничава пътя на коша. Кое е важното?","При повдигане има риск от смачкване между коша и носача.","Планирайте движенията така, че тялото и кошницата ви да не бъдат заклещени.","Направете пътуването по-бързо, така че кошницата да минава по-бързо.","Избутайте конструкцията с коша настрани.","Точките на прищипване между платформата и околната среда изискват внимателно наблюдение и контролирано движение."],"h2-sicherheitsabstand":["Кога опасната зона на сцената трябва да бъде отцепена?","Под обекта минава трасе на градски транспорт.","Само ако предмет вече е паднал.","Ако трети лица могат да бъдат застрашени от движение или падащи предмети.","Никога, тъй като работната кошница предотвратява всички опасности.","Зоната под и до сцената трябва да бъде защитена срещу предвидими опасности."],"h2-korbtor":["Какво се отнася за входната врата на работния кош?","Вече сте на работна височина.","Оставете вратата отворена, за да можете да излезете по-бързо.","Завържете вратата постоянно отворена с въже.","Дръжте вратата затворена според предоставения заключващ механизъм.","Предоставените ключалки са част от предпазните мерки срещу падане от работния кош."],"h2-energieleitung":["Какво се прилага, ако въздушна линия не е безопасно изключена?","Работите с автовишката близо до тях.","Осигурете определени безопасни разстояния и необходимите защитни мерки.","Преместете кошницата точно пред линията, стига да не бъде докосната.","Доверете се на пластмасовите гуми и работете без пропуски.","Електрически прекъсвания са възможни и без директен контакт; Необходими са безопасни разстояния."],"h2-schwanken":["Работният кош започва да се люлее необичайно силно. Кое е правилното?","Движението вече не се контролира.","Регулирайте неконтролируемо с бързи противодействия.","Спрете движението и проверете причината или работните условия.","Добавете допълнителни хора към кошницата, за да стане по-тежка.","Необичайната вибрация може да показва неподходящи работни условия или неизправност."],"h2-ladegeraet":["Кабелът за зареждане на електрическото ниво е повреден. какво правиш","При свързване се вижда повредена изолация.","Докоснете повредата с мокри ръкавици.","Натиснете щепсела в контакта възможно най-силно.","Не започвайте процеса на зареждане и занесете кабела на професионална проверка.","Повреденото електрическо окабеляване крие риск от токов удар и пожар."],"h2-gelaenderanbau":["Можете ли сами да премахнете парапета, за да се приближите?","Компонент предотвратява приближаването на хора до работната площадка.","Не модифицирайте или премахвайте защитните устройства сами.","След повдигане развийте парапета и го монтирайте по-късно.","Продължете да работите без парапет, докато някой стои до него.","Структурните защитни устройства не могат да се променят без допустими спецификации и мерки за безопасна подмяна."],"h2-lastkran":["Може ли платформата да се използва като кран за повдигане на товар?","Материалът трябва да се транспортира свободно окачен до работния кош.","Всеки път, когато теглото е по-малко от собственото ви телесно тегло.","Само ако производителят и оборудването изрично разрешават тази специална употреба.","Просто прикрепете кука към парапета и повдигнете материала.","Въздушните работни платформи не са проектирани автоматично за работа с кран или допълнителни висящи товари."],"h2-arbeitsvorbereitung":["Какво включва подготовката за ново местоположение?","Още не познавате строителната площадка.","Просто преценете разстоянието до най-близкия паркинг.","Независимо от обкръжението, разширете го напълно веднага.","Оценете опасностите, почвата, маршрутите за движение, спасяването и годността на оборудването.","Оценката на риска, свързана с местоположението, е предпоставка за безопасни работни условия."],"h2-kabelschlaufe":["Захранващ кабел лежи през пътя на сцената. Кое е правилното?","Кабелът може да се заклещи по време на движение.","Разчистете пътя и предпазете електрическите кабели от повреда.","Използвайте кабела с колелата като пътен праг.","Повдигнете кошницата, без да проверявате пода.","Прегазени или смачкани кабели могат да причинят електрически и механични опасности."],"h2-leitungsnaehe":["Кой изяснява защитните мерки на електрическа система?","Платформата трябва да работи близо до живо оборудване.","Човекът в кошницата решава само на око.","Включете отговорните органи и приложете координирани защитни мерки.","Разстоянието се определя само след започване на работата.","Работата в близост до електрически системи изисква планирани и координирани защитни мерки."],"h2-funkkommunikation":["Защо сигналите между пода и кошницата трябва да са ясни?","Човек на земята помага при маневриране.","Така че няколко души могат да дават противоречиви инструкции едновременно.","За да може аварийното спускане да се изпробва без инструкции.","Така че движенията се извършват само след ясна комуникация.","Ясната комуникация намалява неправилните движения и сблъсъци при маневриране."],"h2-neuebedienung":["Вие преминавате към различен тип сцена. Какво се изисква?","Работните функции се различават значително.","Специфична инструкция за устройството преди самостоятелна употреба.","Просто четене на фирменото лого на устройството.","Пробно шофиране с вече удължена кошница без инструкции.","Квалификацията сама по себе си не замества обучението в конкретния тип устройство."],"h2-steckanschluss":["Какво трябва да проверите, преди да свържете зарядно устройство?","Електрическа въздична работна платформа трябва да бъде заредена.","Използвайте всеки контакт, независимо от състоянието и предпазителя.","Проверете подходящата връзка и неповредения кабел според инструкциите на производителя.","Редовно изваждайте щепсела от контакта по време на зареждане.","Подходящите и здрави електрически връзки предпазват от токов удар и пожар."],"h2-absperrpersonal":["Човек влиза в отцепената зона по време на работа по повдигане. какво правиш","Можете да видите човек директно под работната кошница.","Продължете да шофирате, ако лицето носи защитна каска.","Пуснете инструмент в тяхната посока като предупредителен сигнал.","Спрете опасното движение и разчистете района.","Бариерата не замества наблюдението на опасната зона по време на работа."],"k2-arbeitsplanung":["Какво трябва да включва подготовката за работа преди работа с кран?","Товарът, местоположението и транспортният маршрут все още не са съгласувани.","Първо вдигнете най-тежкия товар без допълнително планиране.","Маркирайте само най-краткия маршрут на пода на залата.","Уточнете предварително товароносимостта, сапаните, пътя на товара и опасната зона.","Планираното движение на крана изисква подходящо манипулиране на товара, безопасни маршрути и координирани защитни мерки."],"k2-hakenposition":["Как се позиционира куката на крана над товара преди повдигане?","Точките на закрепване са под крана.","Възможно най-вертикално над центъра на тежестта според стопа.","Изместено много настрани, така че товарът да се люлее по-бързо.","Във всеки случай на външния ръб на товара, независимо от центъра на тежестта.","Вертикалното прилагане на сила и подходящите точки за закрепване намаляват страничното движение и неконтролираните движения."],"k2-hakengabel":["Товарната кука показва забележима деформация. Какво се прилага?","Куката изглежда огъната от обичайното си състояние.","Огънете обратно деформацията със следващото натоварване.","Спрете работата на крана и проверете куката от експерт.","Прикрепете само леки товари и продължете да работите.","Деформацията може да повлияе на безопасността на куката; неразрешено по-нататъшно използване не е разрешено."],"k2-zugueberlast":["Бремето е по-тежко, отколкото първоначално се предполагаше. какво правиш","Нова информация за теглото възниква по време на подготовката.","Заменете предпазния резерв с по-бързо повдигане.","Игнорирайте теглото на товара, като го прикрепите към друга точка.","Определете действителното натоварване и проверете отново границите на натоварване.","Безопасното повдигане изисква надеждни данни за товара и съответствие с всички съответни товароносимости."],"k2-arbeitskorb":["Може ли обикновена кука на кран лесно да транспортира хора?","Човек иска да стигне до високо работно място.","Не, превозът на пътници изисква разрешени специални съоръжения и мерки.","Да, ако човекът се държи за въжето на прашката.","Да, щом ударът се извършва особено бавно.","Транспортирането на хора е разрешено само при специални условия, предвидени за тази цел."],"k2-bruecke":["Мостов кран се движи по пътека на обща зала. Кое е важното?","Служителите остават под транспортния маршрут.","Карайте с товара точно над главите на служителите.","Ефективно поддържайте пътя на товара и зоната за движение чисти и сигурни.","Използвайте само предупредителния клаксон вместо допълнителни мерки.","Хората, изложени на риск, не трябва да бъдат под окачени товари или на пътя им за транспортиране."],"k2-zweitekrane":["Два крана работят в припокриваща се зона. Какво е необходимо?","Стрели или товари могат да се сблъскат един с друг.","Двамата кранисти работят едновременно без предварителна уговорка.","Движенията са умишлено ускорени, за да се избегнат кръстовища.","Координирайте операциите и вземете подходящи мерки за предотвратяване на взаимни заплахи.","Припокриващите се работни зони изискват координирана оперативна организация и подходящи предпазни мерки."],"k2-pruefbuch":["Какво е значението на задължителния периодичен преглед на крана?","Машината се използва редовно в експлоатация.","Допълва оперативния контрол с предписаната експертиза.","Той постоянно замества всяка визуална проверка преди започване на работа.","Изисква се само след катастрофа.","Периодичните проверки и текущият оперативен контрол имат различни задачи."],"k2-absetzflaeche":["Предвидената зона за поставяне е неравна. как действаш","Товарът може да се преобърне при поставяне.","Поставете товара в единия ъгъл и го оставете да виси непроменен.","Подгответе подходящи, носещи и стабилни основи или повърхности.","Поставете един човек под товара, докато спускате.","Зоните за поставяне трябва да поддържат товара безопасно и да предотвратяват опасни движения на обръщане или търкаляне."],"k2-anfahrbereich":["Преди кранът да започне да се движи, в зоната за движение има един човек. какво правиш","Трасето е блокирано от човек.","Избутайте човека настрани с кратко пробно шофиране.","Тръгнете само с крайния изключвател без визуална проверка.","Започнете движение само когато опасната зона е свободна и безопасна.","Шофирането и въртенето не трябва да застрашават хората."],"k2-schlaffseil":["Защо подемното въже не трябва да се отпуска неконтролируемо, когато е поставено долу?","Товарът е включен, куката е спусната още повече.","Така че въжето и куките да не се заклещват или подлагат на неконтролирано натоварване.","Така че след това товарът да може да бъде издърпан странично от въжето.","Така че сапаните се отделят сами от куката.","Неконтролираното прокарване на кабели може да доведе до заплитане и опасни движения на товара."],"k2-pendel":["Товарът, който се транспортира, започва да се люлее. Кое е правилното?","Товарът се движи странично повече от планираното.","Компенсирайте с бързи контрадвижения и пълна скорост.","Намалете движенията по контролиран начин и успокойте пътуването без хора в опасната зона.","Дръжте люлеещия се товар с голи ръце.","Осцилиращите товари могат да засегнат хора и съоръжения; спокойните движения намаляват риска."],"k2-funkakku":["Радио управлението на кран е със слаба батерия. Какво се прилага?","Връзката може да се скъса по време на повдигане.","Повдигнете товара бързо, преди управлението да се повреди.","Ако връзката се загуби, преместете товара, като издърпате прашката.","Осигурете надеждна контролна връзка преди употреба.","Надеждното управление и комуникация са предпоставка за контролирани движения на крана."],"k2-mehrereanschlaeger":["Двама души подават различни сигнали на оператора на крана едновременно. Кое е правилното?","Знаците си противоречат.","Прекъснете движението и изяснете ясна отговорност.","Предпочитайте знака на по-далечния човек.","Продължете движението според собственото си усещане.","Шофьорите на кранове се нуждаят от ясна и недвусмислена комуникация, особено когато товарните маршрути са объркващи."],"k2-endabschaltung":["Защо крайният превключвател не трябва да се използва неправилно като нормално ограничение на хода?","Товарът често се премества до максималното разстояние на повдигане.","Крайните изключватели обикновено позволяват по-бързо повдигане без видимост.","Крайните изключватели са предпазни устройства и не заместват контролираната работа.","Те трябва да бъдат удряни възможно най-силно с всеки удар.","Предпазните устройства служат за защита срещу опасности и не трябва да се използват прекомерно, както е планирано."],"k2-wetterbeobachtung":["Вятърът се увеличава значително с голямо натоварване на площта. Какво се изисква?","Голямата площ на компонентите действа като платно.","Винаги повдигайте товара по-високо, така че вятърът да има по-малко влияние.","Сменете паласките с по-тънки.","Оценете границите на вятъра и експлоатационните ограничения и коригирайте повдигането, ако е необходимо.","Вятърът може да генерира значителни допълнителни сили и движения на махалото, особено при товари с голяма площ."],"k2-ortswechsel":["Какво е важно при преместване на мобилен кран на ново място?","Променят се условията на подпочвата и опората.","Проверете местоположението на стойката и опората, преди да вземете товара отново.","Приложете настройките от предишното местоположение без проверка.","Регулирайте опората по време на повдигане.","Всяко място за монтаж може да има различни условия на натоварване на земята и опората."],"k2-betriebsbereich":["Кран трябва да работи през улица. Какво трябва да се изясни?","Трети лица могат да влязат в опасната зона.","Обезопасявайте пътя само с предупредителен клаксон.","Необходими локдауни, гласуване и мерки за защита пред хъба.","Повдигнете товара над превозните средства възможно най-бързо, без да го обезопасявате.","Безопасното управление на трафика предотвратява ненужен риск за трети страни от товари и движения на крана."],"k2-hochheben":["След пробното повдигане товарът виси явно криво. Кое е правилното?","Фокусът очевидно е бил преценен погрешно.","Продължете да повдигате, така че дисбалансът да се коригира сам.","Накарайте един човек да изтегли наклонения товар.","Поставете товара безопасно и проверете отново закрепването и центъра на тежестта.","Тестовото повдигане се използва за откриване на неправилно закрепване и нестабилни позиции на товара преди транспортиране."],"k2-schwebelast":["Можете ли да оставите повдигнат товар да виси без надзор?","Смяната свършва, но товарът все още е на куката.","Не, спуснете товара безопасно и закрепете правилно крана.","Да, ако кранът е блокиран срещу отдалечаване.","Да, стига да има предупредителен знак на земята.","По принцип висящите товари не трябва да се оставят без надзор."],"k2-mitnahme":["Колега иска да се вози на кран товар. Какво се прилага?","Товарът трябва да се транспортира до по-висока точка.","Ездата е разрешена, ако колегата носи каска.","Хора не могат да се транспортират или да се прикачват към нормални товари.","Возенето винаги е разрешено, стига колегата да е познат на машиниста на крана.","Носенето на хора заедно с товари създава значителни рискове от падане и смачкване."],"k2-warnsignal":["Работна предупредителна система на крана не работи. Кое е правилното?","Вече не е възможно да се предостави предупреждение преди потегляне.","Игнорирайте системата, когато двигателят работи.","Заменете предупреждението за постоянно, като докоснете корпуса.","Докладвайте за повреда, свързана с безопасността, и прекъснете операциите според инструкциите.","Необходимите предупредителни устройства трябва да работят, така че хората да бъдат защитени своевременно."],"k2-schneekante":["Мобилният кран трябва да бъде поддържан върху замръзнала, неравна земя. Какво се прилага?","Почвата може да загуби своята носеща способност, когато се размрази.","Оценете товароносимостта и опорната ситуация при действителни условия.","Замръзналата почва винаги има някаква носимоспособност.","Поставете опори само върху малки камъни.","Температурата, влажността и структурата на почвата влияят върху носещата способност на крановете."],"k2-laufkatze":["Количка се движи към препятствие. как действаш","В района на шофиране има предмет.","Бавно избутайте предмета с товара.","Спрете своевременно движението и безопасно отстранете препятствието.","Карайте покрай препятствието с повишена скорост.","Движенията на крана трябва да се направляват по такъв начин, че да няма сблъсъци с препятствия."],"k2-anschlagaufnahme":["Трябва да вземете товар, като използвате непредназначено ухо. Кое е правилното?","Окото може да бъде предназначено само за монтиране на капак.","Всеки отвор е подходящ за пълно натоварване на крана.","Зареждайте отвора само с двама души едновременно.","Проверете капацитета на натоварване и годността на точката за закрепване преди употреба.","Не всяко съществуващо ухо е стабилна точка на закрепване за товари на крана."],"l2-seilbruch":["Въже показва няколко счупени отделни жици. Кое е правилното?","Точките на скъсване са в областта на носещото въже.","Не продължавайте да използвате подемно оборудване и го предайте на професионална оценка.","Огънете краищата на жицата назад с голи ръце.","Продължете да използвате въжето, ако товарът е особено лек.","Прекъсването на проводниците може да бъде критерий за изхвърляне; Повредените въжета трябва да бъдат оценени професионално."],"l2-schaekel":["Какво е от решаващо значение при използването на окови?","Скоба свързва прашката и товара.","Сменете болта с произволен пирон.","Проверете за подходяща товароносимост, неповредено състояние и правилни болтове.","Преценете капацитета на натоварване въз основа на цвета.","Скобите трябва да бъдат с подходящ размер, използвани изцяло и в предвидената посока на товарене."],"l2-tragfaehigkeit":["Какво трябва да имате предвид, когато използвате няколко нишки?","Нишките вървят под ъгъл спрямо вертикалата.","Просто съберете товароносимостта на всяка нишка по желание.","Закачете товара само на най-лекия кичур.","Вземете предвид товароносимостта на целия тип котва и ъгъл.","Ъгълът на наклона и ефективният брой нишки оказват значително влияние върху допустимото натоварване."],"l2-schweissnaht":["Може ли импровизирана точка за закрепване да бъде заварена към товар?","Няма подходящи обозначени места за приемане на товара.","Използвайте само правилно проектирани и одобрени точки за закрепване.","Всеки заваръчен шев е достатъчен без тестване.","Вкарайте кука през отвор в ламарината.","Точките за закрепване трябва да бъдат доказано подходящи за силите, включени в повдигането."],"l2-einseitig":["Товарът е значително по-тежък от едната страна. Как го правиш?","Центърът на тежестта е извън геометричния център.","Оставете всички нишки с еднаква дължина, независимо от центъра на тежестта.","Определете центъра на тежестта и регулирайте съответно позицията.","Първо повдигнете товара до пълна височина на повдигане.","Ако центърът на тежестта е извън центъра, товарите могат неочаквано да се наклонят или отделните нишки могат да бъдат претоварени."],"l2-kettenriss":["Какво се отнася за верижна прашка с видими пукнатини?","Има пукнатина в едно от звената на веригата.","Маркирайте пукнатината с боя и я повдигнете непроменена.","Увийте връзката с тел и я използвайте повторно.","Свалете незабавно веригата и уведомете отговорното лице.","Пукнатините в носещите звена на веригата са свързани с безопасността повреди и изискват извеждане от експлоатация."],"l2-lastfuehrung":["Как се носи голям товар, когато има опасност от завъртане?","Товарът може да се люлее настрани по време на повдигане.","Използвайте подходящи насочващи устройства и безопасно разстояние.","Дръжте товара директно между ръцете си, докато шофирате.","Стъпете под товара и го подравнете отдолу.","Воденето на товара не трябва да води до попадане на ръце или тела в опасната зона."],"l2-schnueren":["Какво е важно при закрепването на връзките?","Прашката се насочва около компонент.","Приемете същата товароносимост като всеки друг тип котва.","Спазвайте пригодността на типа закрепване и допустимото натоварване според маркировката.","Издърпайте приспособлението заедно до произволна степен, без да проверявате.","Видът на приставката за връзки може да промени допустимия капацитет на натоварване и трябва да се използва правилно."],"l2-winkelmesser":["Защо не можете да пренебрегнете плоския ъгъл на нишка?","Две въжета за прашка минават почти хоризонтално спрямо товара.","Плоският ъгъл автоматично прави нишката по-здрава.","Натоварването винаги се разпределя равномерно, независимо от ъгъла.","Големите сили на нишката могат да надвишат допустимия капацитет на натоварване.","С увеличаването на ъгъла спрямо вертикалата напреженията върху нишките се увеличават."],"l2-heisse-last":["Какво трябва да проверите за горещ товар?","Една стоманена част беше наскоро термично обработена.","Спазвайте температурните граници на сапаните и подходящия избор.","Всеки текстилен слинг издържа на всякакви температури.","Етикетирането няма значение, когато е горещо.","Температурата може да повлияе на допустимата товароносимост на сапаните."],"l2-abstand":["Можете ли да поставите пръстите си под товара, когато го поставяте?","Товарът трябва да се приземи върху повърхност с милиметрова точност.","Да, ако носите работни ръкавици.","Не, спазвайте дистанция и използвайте подходящи помощни средства.","Да, ако движението на крана е особено бавно.","Части от тялото между товара и основата могат да се заклещят."],"l2-verbindung":["Свързващата връзка на веригата на прашката не е заключена. Какво се прилага?","Закопчалката липсва.","Използвайте резето без ключалката, когато никой не гледа.","Залепете елемента с лепяща лента.","Не удряйте, докато закопчалката не е правилно закрепена.","Свързващите елементи трябва да бъдат закрепени напълно и в съответствие с техния дизайн."],"l2-lasthaken":["Какво проверявате, когато висите на кука на кран?","В куката трябва да се насочат няколко сапана.","Осигурете сигурно прилягане и годност на куките и окачването.","Поставете прашки на върха на куката.","Сменете ключалката на куката с кабелна връзка.","Силата трябва да се прилага по предназначение в определените зони."],"l2-fasern":["Повдигащата лента показва сериозно нагрубяване и увреждане на влакната. Кое е правилното?","Поддържащите влакна са видимо повредени.","Покрийте повредата с друг възел.","Отделете колана за повдигане и го проверете от специалист.","След това повдигнете товара по-бързо.","Повредените носещи влакна могат значително да намалят товароносимостта на повдигащата лента."],"l2-anheben":["Какво се прилага веднага след първия сантиметър повдигане?","Товарът просто се повдига от основата си.","Издърпайте товара до пълната му височина без контрол.","Проверете под товара дали сапаните са опънати.","Проверете позицията на стоп, баланса и поведението на движение.","Контролирано тестово повдигане прави възможните нестабилности видими преди по-нататъшно транспортиране."],"l2-lastgewichte":["Теглото на товара е неизвестно. Кое е правилното?","Компонентът няма маркировка за тегло.","Определете допустимото тегло, преди да изберете сапани.","Преценете теглото въз основа на цвета на товара.","Използвайте всяка прашка с двойна дължина.","Без известно или надеждно определено тегло годността на сапаните не може да бъде проверена със сигурност."],"l2-lose-teile":["Има разхлабени инструменти върху товара, който трябва да се повдигне. какво правиш","Инструментите могат да паднат при повдигане.","Дръжте инструментите с една ръка, когато шофирате.","Отстранете или закрепете ефективно разхлабените предмети преди повдигане.","Повдигнете товара малко по-бързо, за да не се хлъзне нищо.","Разхлабените предмети могат да паднат и да застрашат хората в района."],"l2-wind":["Голям товар е прикрепен при силен вятър. Какво се прилага?","Компонентът предлага на вятъра голяма повърхност за атака.","Повдигнете товара, без да се съобразявате с люлеещите се движения.","Допълнителни хора трябва да държат товара директно.","Оценете условията на вятъра и се въздържайте от повдигане, ако ситуацията не е безопасна.","Силите на вятъра могат да повлияят на насочването на товара и стабилността по време на транспортиране."],"l2-unterlage":["Защо подходящите документи са важни при отбиването?","Кръгъл товар би се търкулнал на земята.","Поставете товара плътно надолу и го осигурете срещу търкаляне, ако е необходимо.","Оставете товара да стои директно върху сапаните.","Пъхайте документите под товара само след като са били поставени.","Подходящи опори предотвратяват преобръщане и нежелани движения при лягане."],"l2-transportweg":["Какво трябва да се съгласува преди транспортирането на товара?","Товарът се премества в няколко работни зони.","Само очакваната продължителност на хъба.","Безопасен товарен път, комуникация и необходими бариери.","Един човек трябва да показва пътя под товара.","Транспортирането на товари изисква безопасни маршрути и ясна координация."],"l2-schutzschlauch":["На какво трябва да обърнете внимание, когато използвате сапани със защитен маркуч?","Една лента лежи срещу грапав ръб.","Всеки тънък плат замества подходящата защита на ръбовете.","Защитен маркуч премахва всяка допустима граница на натоварване.","Изберете защитно оборудване според изискванията за пригодност и приложение.","Защитното оборудване трябва да съответства на материала, ръба и предвиденото натоварване."],"l2-reinigung":["Повдигаща лента е била замърсена с неизвестен химикал. Кое е правилното?","Лентата вече не може да бъде ясно оценена.","Спрете да използвате и изяснете професионално съвместимостта или състоянието.","Почистете с всеки разтворител и продължете да повдигате незабавно.","Игнорирайте химикала, докато лентата е суха.","Химикалите могат да повлияят на здравината на текстилните сапани."],"l2-aufhaengung":["Какво проверявате за множество нишки на връзката за окачване?","Две нишки се поставят заедно в суспензия.","Кичур може да се премести във върха на куката по желание.","Всички свързващи елементи трябва да са подходящи и подредени по предназначение.","Пръстен с пукнатина може да се използва за малки товари.","Ограничителите и свързващите елементи трябва да са носещи и правилно разположени."],"l2-einweiserrolle":["Какво се прилага, ако нападателят и операторът на крана нямат видимост?","Носач блокира изгледа на точката на пускане.","Координирайте, като извикате няколко човека без отговорност.","Преместете товара въз основа на шум без инструкции.","Организирайте ясна, сигурна комуникация и я спрете, ако е неясна.","Липсата на видимост трябва да се компенсира с ефективна координация и сигурна комуникация."],"l2-ausserbetrieb":["Повредена прашка беше подредена. Какво друго е важно?","Той остава свободно достъпен заедно с готови за използване ресурси.","Осигурете срещу по-нататъшно случайно използване и информирайте отговорното лице.","Върнете продукта немаркиран в инвентара.","Използвайте го отново само когато носите особено лек товар.","Изхвърлените сапани трябва да бъдат надеждно защитени преди по-нататъшна употреба."],"b2-schwenkradius":["Защо задният радиус на въртене на багера е критичен?","Опашката се движи върху ограничена работна зона.","Трети лица могат да бъдат захванати от люлеещата се надстройка.","Радиусът на въртене не оказва влияние върху хората до машината.","Задната част винаги се движи само по посока на движението.","При завъртане зад машината също възниква опасна зона."],"b2-verkehrseinweiser":["Как се осигурява движението при шофиране, когато видимостта е затъмнена?","Багерът трябва да маневрира зад препятствие.","Карайте без да виждате сигналите на сигнализатора.","Ако е необходимо, организирайте подходящо обучение с ясна комуникация.","Осигурете движението на заден ход само с един клаксон.","Объркващите маршрути изискват ефективни мерки за предотвратяване на сблъсъци и заклещване."],"b2-standplatz":["Какво се отнася за стойка на багер на наклон?","Подът е наклонен и може да е хлъзгав.","Машината може да се изпъва колкото иска при всякакъв наклон.","Винаги поставяйте багера върху рохкав слой пръст.","Проверете стабилността и работните граници на машината преди употреба.","Наклонът на склона и почвата имат значително влияние върху стабилността."],"b2-oberleitung":["Защо трябва да се планира разстоянието на стрелата от електропроводите?","Стрелата може да се доближи до кабела при завъртане.","Възможен е и електрически пробив без директен контакт.","Само кофата може да провежда електричество, не и стрелата.","При суха почва всяко разстояние автоматично е безопасно.","Ограниченията на употреба и защитните разстояния трябва да бъдат изяснени преди да се приближите до електрическите системи."],"b2-fremdperson":["Случаен минувач влиза на строителната площадка в зоната за панорамиране. Кое е правилното?","Човекът внезапно застава близо до кофата на багера.","Вдигнете лопатата нагоре и я завъртете над човека.","Незабавно спрете движението и разчистете района.","Просто продължете да наблюдавате човека от страничния прозорец.","Хората в опасната зона не трябва да бъдат застрашавани от работни движения."],"b2-parkstellung":["Как се обезопасява земекопна машина след приключване на работата?","Багерът остава без надзор на строителната площадка.","Оставете лъжицата на нивото на главата.","Оставете двигателя да работи без надзор.","Оставете работното оборудване, обезопасете машината и предотвратете неоторизирана употреба.","Правилното паркиране намалява случайното движение и неразрешения достъп."],"b2-eigenlast":["Защо ограниченията на оборудването са решаващи при повдигане с багер?","На стрелата трябва да се поеме тежък товар.","В противен случай стабилността и допустимата товароносимост могат да бъдат превишени.","Всяка машина може да повдигне всякакъв товар, стига кофата да пасне.","Само дължината на въжето на прашката определя риска.","Информацията за повдигане и товароносимост зависи от оборудването и ситуацията на приложение."],"b2-untergrundhohlraum":["Подът над старо мазе може да е кух. какво правиш","Трябва да закарате багера в района.","Пресечете мястото с максимална инерция.","Изяснете товароносимостта и възможните кухини, преди да продължите.","Просто поставете тежък товар върху повърхността.","Кухините могат да се срутят под тежестта на машината и да причинят повреда на машината."],"b2-feuchtigkeit":["След силен дъжд насипът става мек. Кое е правилното?","В близост до ръба на насипа работи багер.","Преместете машината по-близо до ръба, за да увеличите обхвата.","Игнорирайте промените до края на смяната.","Преоценете почвата и условията на стабилност.","Проникването на влага може да промени носещата способност и стабилността на насипите."],"b2-bodenprobe":["Защо плановете на тръбопровода трябва да се проверяват преди изкопни работи?","Под планирания изкоп могат да минават кабели.","За да могат да се идентифицират линиите и да се планират подходящи мерки за сигурност.","Така че разкопките могат да се извършват по-бързо, независимо от системи на трети страни.","Тъй като машините никога не трябва да се използват в близост до кабели.","Подземните захранващи линии изискват надеждно изясняване на местоположението преди изкопни работи."],"b2-maschinenzugang":["Какво важи при влизане и излизане от земекопната машина?","Машината е на неравен терен.","Плъзнете хидравличната линия надолу от кабината.","Използвайте определени стъпала и осигурете сигурна опора.","Скочете върху въртящото се рамо, докато машината работи.","Безопасните изкачвания и подходящите точки за спиране намаляват риска от падане и премазване."],"b2-kupplung":["Как се проверява нов багер след монтаж?","Кофата е свързана чрез бърз съединител.","Оценявайте лъжицата само визуално от по-голямо разстояние.","Стъпете директно под повдигнатата лъжица.","Осигурете правилно заключване и предписани стъпки за управление.","Приставките, които са неправилно заключени, могат да се разхлабят и да застрашат хората."],"b2-hydraulikwartung":["Защо хидравличните тръбопроводи не могат да се отварят под налягане?","Трябва да се смени маркуч.","Изтичащата течност може да причини сериозни наранявания поради високо налягане.","Налягането винаги предотвратява изтичането на масло.","Отворената линия може безопасно да се провери с ръцете ви.","Течността под високо налягане може да проникне в тъканта и изисква безопасно освобождаване на налягането."],"b2-fahrweg":["Трябва да преминете през временен строителен мост. какво проверяваш","Мостът е проектиран само за определени натоварвания.","Дали цветът на моста съвпада с машината.","Товароносимост и пригодност за теглото и размерите на машината.","Само дали лека кола вече е минала по моста.","Временните конструкции могат да се използват само в рамките на доказаната им носимоспособност."],"b2-baggertransport":["Какво е важно при транспортиране на багер на нисък товарен товар?","Машината се откарва до следващата строителна площадка.","Оставете работното оборудване да стърчи свободно над ръба.","Дръжте вратата на кабината отворена, докато шофирате.","Осигурете машината в съответствие с транспортните спецификации и проверете оборудването за товарене.","Транспортните ключалки и подходящи съоръжения за товарене предотвратяват подхлъзване и падане."],"b2-schaufelfuellung":["Защо колесният товарач не може да се движи бързо с високо вдигната кофа?","Товарът е тежък и теренът е неравен.","Високият център на тежестта може да увеличи риска от преобръщане и проблеми с видимостта.","Кофата се стабилизира автоматично при високи скорости.","Височината на лопатата не е от значение за стабилността.","Повишеният център на тежестта обикновено влошава стабилността при шофиране и завиване."],"b2-fussgaenger":["Как се държите, когато маневрирате до пешеходци?","Достъпът до строителната площадка също е пешеходна пътека.","Използвайте лопатата, за да насочите пешеходците отстрани.","Извършвайте движение само когато зоната е безопасно свободна и управляема.","Просто натиснете веднъж и карайте бавно без видимост.","Трафикът на превозни средства и пътници трябва да бъде ефективно разделен или безопасно координиран."],"b2-ueberlastwarnung":["При повдигане машината отчита претоварване. какво правиш","Повдигнатият товар достига допустимите граници.","Изключете предупреждението и продължете да го повишавате без промяна.","Затегнете внезапно товара, докато машината работи.","Спрете опасните движения и безопасно коригирайте ситуацията на натоварване.","Предупрежденията за претоварване показват възможни нарушения на ограниченията и рискове за стабилността."],"b2-wasserleitung":["Докато се копае, се открива неизвестна тръба. Какво се прилага?","Линията не е показана в строителните планове.","Спрете работата в засегнатата област и накарайте линията да бъде идентифицирана професионално.","Опитайте да преместите линията с лопатата на багера.","Продължете да копаете директно под линията, без да проверявате.","Непознатите линии могат да причинят електрически, газови или водни опасности."],"b2-hangefahrt":["Как се кара багер по стръмен наклон?","Планираният маршрут води по склон.","Карайте през наклона, независимо от ограниченията на производителя.","Спазвайте допустимия наклон и предписания стил на шофиране на машината.","Завъртете стрелата навън, за да балансирате превозното средство.","Допустимият наклон зависи от машината, повърхността и информацията на производителя."],"b2-schlechtebeleuchtung":["Когато работите в тъмна яма, видимостта е недостатъчна. Кое е правилното?","Почти не виждате хора и препятствия.","Увеличете скоростта на копаене, за да завършите операцията бързо.","Не използвайте светлините, докато двигателят работи.","Спрете работата, докато опасните зони станат достатъчно видими.","Необходима е безопасна видимост на зоните за шофиране и работа за контролирани движения на машината."],"b2-kettenverschleiss":["При ежедневната проверка се забелязва повредена гъсеница. какво правиш","Верижната връзка показва ясни щети.","Не продължавайте да използвате машината безконтролно и докладвайте за всякакви щети.","Продължете да шофирате с висока скорост, така че веригата да се изправи.","Продължете да работите само върху мека земя без проверка.","Повредата на задвижването може да наруши управляемостта и стабилността."],"b2-ladearbeiten":["Товарите камион с багера. Кое е важното?","Шофьорът на камиона остава близо до зоната за товарене.","Завъртете кофата над незащитената шофьорска кабина.","Предотвратете оставането на хора в опасната зона и координирайте процесите.","Започнете зареждането, без да комуникирате с драйвера.","При товарене има опасност от падащ материал и люлеещи се движения."],"b2-arbeitsunterbrechung":["Прекъсвате изкопните работи за среща. Какво се прилага?","Машината трябва да престои няколко минути, без да се работи.","Оставете вдигнатата лопата като маркер.","Оставете машината без надзор с включено тягово задвижване.","Поставете машината безопасно и я обезопасете срещу неволно използване.","Дори кратките прекъсвания изискват безопасно състояние на машината."],"b2-rollmaterial":["Разхлабеният материал може да падне при транспортиране с колесния товарач. Кое е правилното?","Товарачът се движи близо до служителите.","Вземете товара безопасно и изберете безопасен стил на шофиране с подходяща позиция на лопата.","Вдигнете лопатата възможно най-високо, така че околното пространство да има ясна видимост.","Вземете товара, без да ограничавате пълненето на кофата.","Разхлабените товари, високите позиции на кофата и лошата видимост могат да застрашат хората и трафика."]};
